void *my_memset(void *s, int c, size_t n) {
    unsigned char *p = (unsigned char *)s;
    unsigned char v = (unsigned char)c;
    for (size_t i = 0; i < n; ++i) p[i] = v;
    return s;
}

void *my_memcpy(void *restrict dest, const void *restrict src, size_t n) {
    unsigned char *d = (unsigned char *)dest;
    const unsigned char *s = (const unsigned char *)src;
    for (size_t i = 0; i < n; ++i) d[i] = s[i];
    return dest;
}

void *my_memmove(void *dest, const void *src, size_t n) {
    unsigned char *d = (unsigned char *)dest;
    const unsigned char *s = (const unsigned char *)src;
    if (d == s || n == 0) return dest;
    if (d < s) { for (size_t i = 0; i < n; ++i) d[i] = s[i]; }
    else       { for (size_t i = n; i > 0; --i) d[i-1] = s[i-1]; }
    return dest;
}

int my_memcmp(const void *s1, const void *s2, size_t n) {
    const unsigned char *a = (const unsigned char *)s1;
    const unsigned char *b = (const unsigned char *)s2;
    for (size_t i = 0; i < n; ++i)
        if (a[i] != b[i]) return (int)a[i] - (int)b[i];
    return 0;
}

void *my_memchr(const void *s, int c, size_t n) {
    const unsigned char *p = (const unsigned char *)s;
    unsigned char v = (unsigned char)c;
    for (size_t i = 0; i < n; ++i)
        if (p[i] == v) return (void *)(p + i);
    return NULL;
}

void swap_int(int32_t *a, int32_t *b) {
    if (a == b) return;
    int32_t tmp = *a; *a = *b; *b = tmp;
}

void reverse_string(char *s) {
    if (s == NULL) return;
    size_t len = 0; while (s[len]) ++len;
    for (size_t i = 0, j = (len ? len-1 : 0); i < j; ++i, --j) {
        char t = s[i]; s[i] = s[j]; s[j] = t;
    }
}

int demo_pointer_const(void) {
    int x = 10, y = 7;
    int *const cp = &x;   // 포인터 고정, *cp 수정 가능
    *cp = 42;
    const int *pc = &x;   // 값 읽기전용, 재지정 가능
    pc = &y;
    return *cp + *pc;     // 42 + 7 = 49
}

bool wait_ready(volatile const uint32_t *status, uint32_t mask, int max_iters) {
    if (status == NULL) return false;
    for (int i = 0; i < max_iters; ++i)
        if ((*status & mask) != 0u) return true;
    return false;
}

typedef int32_t (*alu_fn_t)(int32_t, int32_t);
static int32_t op_add(int32_t a,int32_t b){return a+b;}
static int32_t op_sub(int32_t a,int32_t b){return a-b;}
static int32_t op_mul(int32_t a,int32_t b){return a*b;}
static int32_t op_and(int32_t a,int32_t b){return a&b;}
int32_t dispatch(uint8_t opcode, int32_t a, int32_t b) {
    static const alu_fn_t table[] = { op_add, op_sub, op_mul, op_and };
    if (opcode >= sizeof table / sizeof table[0]) return INT32_MIN;
    return table[opcode](a, b);
}

#define POOL_SIZE 1024u
#define ALIGN 8u
typedef struct blk { size_t size; bool used; struct blk *next; } blk_t;
static _Alignas(16) uint8_t g_pool[POOL_SIZE];
static blk_t *g_head = NULL;
static size_t align_up(size_t v,size_t a){return (v+(a-1))&~(a-1);}
static void pool_init(void){ g_head=(blk_t*)(void*)g_pool; g_head->size=POOL_SIZE-sizeof(blk_t); g_head->used=false; g_head->next=NULL; }
void *static_malloc(size_t size){
    if(!g_head) pool_init();
    if(size==0) return NULL;
    size=align_up(size,ALIGN);
    for(blk_t *b=g_head;b;b=b->next){
        if(b->used||b->size<size) continue;
        if(b->size>=size+sizeof(blk_t)+ALIGN){
            blk_t *nb=(blk_t*)(void*)((uint8_t*)b+sizeof(blk_t)+size);
            nb->size=b->size-size-sizeof(blk_t); nb->used=false; nb->next=b->next;
            b->size=size; b->next=nb;
        }
        b->used=true; return (uint8_t*)b+sizeof(blk_t);
    }
    return NULL;
}
static void pool_coalesce(void){
    for(blk_t *b=g_head;b&&b->next;){
        if(!b->used&&!b->next->used){ b->size+=sizeof(blk_t)+b->next->size; b->next=b->next->next; }
        else b=b->next;
    }
}
void static_free(void *ptr){
    if(!ptr) return;
    blk_t *b=(blk_t*)(void*)((uint8_t*)ptr-sizeof(blk_t));
    b->used=false; pool_coalesce();
}

void safe_free(void **pp) {
    if (pp == NULL || *pp == NULL) return;
    free(*pp);
    *pp = NULL;
}

void generic_swap(void *a, void *b, size_t size) {
    if (a == b || a == NULL || b == NULL) return;
    unsigned char *pa = (unsigned char *)a, *pb = (unsigned char *)b;
    for (size_t i = 0; i < size; ++i) {
        unsigned char t = pa[i]; pa[i] = pb[i]; pb[i] = t;
    }
}

struct Unpacked  { uint8_t a; uint32_t b; uint8_t c; }; // 1+3+4+1+3 = 12
struct Reordered { uint32_t b; uint8_t a; uint8_t c; }; // 4+1+1+2  = 8
size_t sizeof_unpacked(void)      { return sizeof(struct Unpacked); }
size_t sizeof_reordered(void)     { return sizeof(struct Reordered); }
size_t offset_of_b_unpacked(void) { return offsetof(struct Unpacked, b); }

int deref_array_pointer(int (*p)[4], size_t i) {
    if (p == NULL || i >= 4) return -1;
    return (*p)[i];
}
size_t count_strings(const char *const *arr) {
    if (arr == NULL) return 0;
    size_t n = 0; while (arr[n] != NULL) ++n; return n;
}
